"""Generate assets/js/archegon-data.js from the RECALCULATED model workbook so the web pages cannot drift
from the spreadsheet. Usage: python3 tools/build_model_data.py path/to/recalculated-model.xlsx
(Recalculate first, e.g. soffice --headless --calc --convert-to xlsx --outdir recalc model.xlsx)."""
import sys, json, openpyxl
wb=openpyxl.load_workbook(sys.argv[1],data_only=True); R=wb['Rates']; C=wb['Control']
key={R.cell(r,1).value:R.cell(r,4).value for r in range(4,90) if R.cell(r,1).value}
d=lambda k: key[k]
M={'version':'v3 · 12 Oct 2026','fx':d('fx_aud_usd'),'fxNzd':d('fx_aud_nzd'),
 'wellCost':{'LOW':d('au_well_cost_low'),'BASE':d('au_well_cost_base'),'HIGH':d('au_well_cost_high'),'ACTUAL':d('au_well_actual_h4')},
 'mwe':{'LOW':d('mwe_per_well_low'),'BASE':d('mwe_per_well_base'),'HIGH':d('mwe_per_well_high')},
 'rigMob':d('au_rig_mob'),'plantUsdKw':d('plant_usd_per_kw'),'omUsdKwYr':d('plant_fom_usd_kw_yr'),
 'dcShellUsdMw':d('dc_shell_usd_mw'),'liquidUsdMw':d('dc_liquid_premium_usd_mw'),'remote':d('dc_remote_loading'),
 'itFitUsdMw':d('it_fitout_usd_mw'),'rackKw':d('gpu_rack_kw'),'coloUsdKwMo':d('rev_colo_usd_kw_month'),'anchorUsdMwYr':d('rev_anchor_lease_usd_mw_yr'),
 'dcOpexUsdMwYr':d('dc_opex_usd_mw_yr'),'wellReplAudYr':d('au_well_replacement_provision'),
 'pue':C['B17'].value,'cf':C['B16'].value,'cont':C['B13'].value,'teamMo':C['B15'].value,'runwayMo':C['B14'].value,'refIt':C['B12'].value,
 'moduleMw':d('module_mw_it'),'unpriced':0,'wacc':d('wacc_base'),'life':d('asset_life_yrs'),'nemPx':d('px_nem_aud_mwh'),'saPx':d('px_sa_aud_mwh'),
 'nzPxNzd':d('px_nz_nzd_mwh'),'cp':d('cp_water'),'t0':d('dead_state_c'),'utilLo':d('exergy_util_low'),'utilHi':d('exergy_util_high'),
 'parEia':d('parasitic_eia'),'parEgs':d('parasitic_egs_stress'),'habKgS':d('hab_closed_loop_kg_s'),'habC':d('hab_wellhead_c'),
 'nzCapexAud':wb['Raise']['B7'].value,
 'check':{'auRaise':wb['Raise']['B14'].value,'contrib':wb['Compute-Revenue']['B31'].value,'breakEven':wb['Funding-Tiers']['B25'].value,
          'firstModule':wb['Funding-Tiers']['B28'].value,'reservoirTest':wb['Gated-Plan']['C6'].value,'lcoe8':wb['Power-Economics']['E16'].value,
          'tiers':[[wb['Funding-Tiers'].cell(r,1).value]+[wb['Funding-Tiers'].cell(r,c).value for c in range(1,200) if wb['Funding-Tiers'].cell(31,c).value in ('IT MW (whole modules)','Total wells','Committed','Contribution/yr')] for r in range(32,42)]}}
open('assets/js/archegon-data.js','w').write('/* GENERATED by tools/build_model_data.py from archegon-model-v3.xlsx. Do not edit by hand. */\nwindow.ARCHEGON_MODEL='+json.dumps(M,indent=1)+';\n')
print('ok',M['check']['auRaise'])
